import {FIELD,ZONES,COORDS,ROLES} from './data.js';
import {activeBookings,availableCount,myBooking,memberOf,canManage,slotsFor} from './core.js';
import {clock,dateKey,addDays,occurrenceDates} from './dates.js';
export const h=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const vals=Object.values;
export function buildViews(ctx){
 const {s,ui,settings,t,now}=ctx,actor=settings.actorId,person=s.profiles[actor],lang=settings.language==='en'?'en-GB':'it-IT';
 const money=c=>new Intl.NumberFormat(lang,{style:'currency',currency:'EUR'}).format(c/100);
 const date=(at,full=false)=>new Intl.DateTimeFormat(lang,{timeZone:'Europe/Rome',weekday:full?'long':'short',day:'numeric',month:'short',...(full?{year:'numeric',hour:'2-digit',minute:'2-digit'}:{})}).format(new Date(at));
 const button=(key,action,attrs='',className='secondary-cta')=>`<button type="button" class="${className}" data-action="${action}" ${attrs}>${h(t(key))}</button>`;
 const badge=(status)=>`<span class="state state-${h(status)}">${h(t('status_'+status))}</span>`;
 const photoAvailable=p=>!!p.photo&&(!p.photo.startsWith('assets/')||ctx.avatarFiles?.has(p.photo));
 const avatar=(p,size='')=>`<span class="person-face ${size}" aria-label="${h(p.name)}"><span aria-hidden="true">${h(p.name.split(/\s+/).slice(0,2).map(x=>x[0]).join(''))}</span>${photoAvailable(p)?`<img src="${h(p.photo)}" alt="${h(p.name)}" data-avatar="${h(p.id)}" loading="lazy">`:''}</span>`;
 const groupName=gid=>s.groups[gid]?.name||'—';
 const groupMembers=gid=>vals(s.memberships).filter(m=>m.groupId===gid&&m.status==='active');
 const upcoming=gid=>vals(s.matches).filter(m=>(!gid||m.groupId===gid)&&m.status==='active'&&Date.parse(m.startsAt)>now).sort((a,b)=>Date.parse(a.startsAt)-Date.parse(b.startsAt));
 const organizer=(g)=>`<p class="organizer-line"><span>${h(t('organizer'))}</span>: <strong>${h(s.profiles[g.ownerId].name)}</strong><span class="demo-chip">${h(t('demo'))}</span></p>`;
 const title=key=>`<h1 class="page-title">${h(t(key))}</h1>`;
 const empty=key=>`<p class="empty-state">${h(t(key))}</p>`;
 const mapLink=(g,m)=>{const venue=m?.venue||g.venue,city=m?.city||g.city,demo=(m?.groupId||g.id).startsWith('bs-');return `<a class="map-link" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(demo?city:venue+' '+city)}">⌖ ${h(venue)} · ${h(city)} ↗</a><small class="muted">${h(t(demo?'noRealVenue':'mapPrecision'))}</small>`;};
 const groupLogo=g=>g.logo?`<img class="group-logo" src="${h(g.logo)}" alt="${h(g.name)}" width="76" height="76">`:`<span class="group-monogram">${h(g.name.slice(0,2))}</span>`;
 const membershipGate=g=>{const pending=vals(s.requests).some(r=>r.type==='membership'&&r.groupId===g.id&&r.personId===actor&&r.status==='pending');return `<section class="membership-gate card panel" aria-label="${h(t('joinFirst'))}"><h2>${h(t(pending?'membershipWaiting':'joinFirst'))}</h2><ol class="membership-steps"><li class="done">${h(t('stepDiscover'))}</li><li class="${pending?'waiting':''}">${h(t('stepJoin'))}</li><li>${h(t('stepBook'))}</li></ol><p>${h(t(pending?'membershipWaitingHint':'membershipRequired'))}</p><button type="button" class="cta" data-action="join-group" data-id="${g.id}" ${pending?'disabled':''}>${h(t(pending?'membershipPending':g.memberApproval?'joinRequest':'join'))}</button></section>`;};
 const matchCard=(m,fromExplore=false)=>{const g=s.groups[m.groupId],booked=activeBookings(s,m.id,now),pending=booked.filter(b=>b.status==='pending').length;return `<button type="button" class="card match-card" data-action="${fromExplore?'open-event':'open-match'}" data-id="${m.id}"><span class="match-symbol" aria-hidden="true">${groupLogo(g)}</span><span class="event-copy"><strong>${h(g.name)}</strong><span>${h(date(m.startsAt))} · ${clock(m.startsAt)}–${clock(m.endsAt)}</span><small>${h(m.venue)}</small><small class="organizer-copy">${h(t('organizer'))}: ${h(s.profiles[g.ownerId].name)}</small></span><span class="match-numbers"><span class="spots">${h(t('available',{n:availableCount(s,m.id,now)}))}</span><b>${money(m.priceCents)}</b>${pending?`<small>${h(t('status_pending'))}: ${pending}</small>`:''}</span></button>`;};
 const personRow=(p,sub='',extras='')=>`<div class="person-row"><button type="button" class="person-link" data-action="open-profile" data-id="${p.id}">${avatar(p)}<span><strong>${h(p.name)}</strong><small>${h(sub||t('role_'+p.role))}</small></span></button>${extras}</div>`;
 function explore(){const q=(ui.exploreSearch||'').toLocaleLowerCase(),today=dateKey(now),tomorrow=addDays(today,1),limit=addDays(today,7);const list=upcoming().filter(m=>{const g=s.groups[m.groupId],text=`${g.name} ${m.venue} ${g.city} ${g.province}`.toLocaleLowerCase();return (!ui.exploreProvince||g.province===ui.exploreProvince)&&text.includes(q)&&(!ui.dateFilter||ui.dateFilter==='all'||ui.dateFilter==='today'&&m.date===today||ui.dateFilter==='tomorrow'&&m.date===tomorrow||ui.dateFilter==='week'&&m.date<=limit||ui.dateFilter==='exact'&&m.date===ui.exactDate);});return `${title('explore')}<div class="filter-panel"><label class="sr-only" for="exploreSearch">${h(t('searchMatches'))}</label><input id="exploreSearch" data-filter="exploreSearch" type="search" placeholder="${h(t('searchMatches'))}" value="${h(ui.exploreSearch||'')}">${provinceFilter('exploreProvince')}<div class="date-filters">${['all','today','tomorrow','week'].map(value=>`<button type="button" data-action="date-filter" data-value="${value}" class="${(ui.dateFilter||'all')===value?'on':''}">${h(t(value==='all'?'allDates':value))}</button>`).join('')}<label class="date-label">${h(t('exactDate'))}<input id="exactDate" type="date" data-filter="exactDate" value="${h(ui.exactDate||'')}"></label></div></div><div class="matches-list">${list.length?list.map(m=>matchCard(m,true)).join(''):empty('noResults')}</div>`;}
 function provinceFilter(key){return `<label class="province-label" for="${key}">${h(t('province'))}<select id="${key}" data-filter="${key}"><option value="">${h(t('allProvinces'))}</option>${['BG','BS'].map(p=>`<option value="${p}" ${ui[key]===p?'selected':''}>${p==='BG'?'Bergamo (BG)':'Brescia (BS)'}</option>`).join('')}</select></label>`;}
 function directory(){const q=(ui.groupSearch||'').toLocaleLowerCase(),list=vals(s.groups).filter(g=>(!ui.groupProvince||ui.groupProvince===g.province)&&`${g.name} ${g.venue} ${g.city} ${g.province} ${g.province==='BS'?'Brescia':'Bergamo'}`.toLocaleLowerCase().includes(q)).sort((a,b)=>a.name.localeCompare(b.name,lang));const mode=ui.groupView||'list';return `${title('groups')}<div class="section-actions">${button('newGroup','create-group','','small-primary')}</div><div class="filter-panel"><label class="sr-only" for="groupSearch">${h(t('searchGroups'))}</label><input id="groupSearch" data-filter="groupSearch" type="search" placeholder="${h(t('searchGroups'))}" value="${h(ui.groupSearch||'')}">${provinceFilter('groupProvince')}<div class="match-tabs" role="tablist" aria-label="${h(t('groups'))}">${['list','map'].map(view=>`<button type="button" role="tab" aria-selected="${view===mode}" data-action="group-view" data-value="${view}">${h(t(view))}</button>`).join('')}</div></div>${mode==='map'?`<div class="demo-map" aria-label="${h(t('map'))}"><span class="map-region region-bg">Bergamo · BG</span><span class="map-region region-bs">Brescia · BS</span>${list.map(g=>{const groupIndex=vals(s.groups).filter(x=>x.province===g.province).findIndex(x=>x.id===g.id);return `<button type="button" class="group-pin" style="left:${g.province==='BS'?60:9}%;top:${20+(groupIndex%5)*14}%" data-action="open-group" data-id="${g.id}"><span aria-hidden="true">●</span> ${h(g.name)}</button>`;}).join('')}</div><p class="muted">${h(t('mapCaption'))}</p><p class="muted">${h(t('mapHint'))}</p>`:''}<div class="directory-list ${mode==='map'?'map-results':''}">${list.length?list.map(g=>`<button type="button" class="card group-item" data-action="open-group" data-id="${g.id}">${groupLogo(g)}<span><strong>${h(g.name)}</strong><small>${h(g.city)} · ${g.province}</small><small>${h(g.venue)}</small><small>${h(t('membersCount',{n:groupMembers(g.id).length}))} · ${h(t('demoGroup'))}</small></span><span aria-hidden="true">›</span></button>`).join(''):empty('noResults')}</div>`;}
 function groupCard(){const g=s.groups[ui.groupId];if(!g)return empty('notFound');const request=vals(s.requests).find(r=>r.type==='membership'&&r.groupId===g.id&&r.personId===actor&&r.status==='pending'),joined=memberOf(s,actor,g.id),manage=canManage(s,actor,g.id),list=upcoming(g.id);return `${button('groups','nav','data-view="groups"','back-link')}<article class="card group-hero"><div class="group-cover">${groupLogo(g)}<span>${h(t('demoGroup'))}</span></div><h1>${h(g.name)}</h1>${organizer(g)}<p>${h(g.description||t(g.storyKey||'bresciaStory'))}</p><h2>${h(t('story'))}</h2><p>${h(g.history||t(g.storyKey||'bresciaStory'))}</p><dl class="info-grid"><dt>${h(t('usualVenue'))}</dt><dd>${h(g.venue)}<small>${h(g.city)} · ${g.province}</small></dd><dt>${h(t('usualDay'))}</dt><dd>${h(t('day'+g.weekday))} · ${g.start}–${g.end}</dd></dl>${mapLink(g)}<h2>${h(t('accessRules'))}</h2><p>${h(t(g.memberApproval?'memberManual':'memberAuto'))}<br>${h(t(g.bookingApproval?'bookingManual':'bookingAuto'))}</p><p class="muted">${h(t('membersVsPlayers'))}</p>${joined?`<p class="member-approved">✓ ${h(t('alreadyMember'))}</p>`:membershipGate(g)}</article><section class="card panel"><h2>${h(t('members'))} (${groupMembers(g.id).length})</h2>${groupMembers(g.id).map(m=>personRow(s.profiles[m.personId],'',m.personId===g.ownerId?`<span class="organizer-badge">${h(t('organizer'))}</span>`:'')).join('')||empty('noMembers')}</section>${manage?`<section class="card panel"><h2>${h(t('accessManagement'))}</h2>${accessForm(g)}<label class="upload-label">${h(t('uploadGroupLogo'))}<input type="file" id="groupLogoUpload" data-group-id="${g.id}" accept="image/png,image/jpeg,image/webp"></label>${button('removeGroupLogo','remove-group-logo',`data-id="${g.id}"`)}${button('requests','nav','data-view="requests"')}${button('newMatch','create-match',`data-id="${g.id}"`)}</section>`:''}<section class="upcoming-section"><h2>${h(t('upcoming'))}</h2>${list.map(m=>matchCard(m)).join('')||empty('noUpcoming')}</section>`;}
 function accessFields(g={}){return `<fieldset><legend>${h(t('accessManagement'))}</legend><label>${h(t('memberApproval'))}<select name="memberApproval"><option value="false" ${!g.memberApproval?'selected':''}>${h(t('memberAuto'))}</option><option value="true" ${g.memberApproval?'selected':''}>${h(t('memberManual'))}</option></select></label><label>${h(t('bookingApproval'))}<select name="bookingApproval"><option value="false" ${!g.bookingApproval?'selected':''}>${h(t('bookingAuto'))}</option><option value="true" ${g.bookingApproval?'selected':''}>${h(t('bookingManual'))}</option></select></label><p class="muted">${h(t('independentRules'))}</p></fieldset>`;}
 function accessForm(g){return `<form id="accessForm" data-form="access" data-id="${g.id}">${accessFields(g)}<button type="submit" class="secondary-cta">${h(t('saveAccess'))}</button></form>`;}
 function groupForm(){const d=ui.drafts?.group||{};return `${title('newGroup')}<form class="card panel form-grid" id="groupForm" data-form="group"><label>${h(t('groupName'))}<input name="name" required maxlength="70" value="${h(d.name||'')}"></label><label>${h(t('city'))}<input name="city" required maxlength="80" value="${h(d.city||'')}"></label><label>${h(t('province'))}<select name="province"><option value="BG" ${d.province==='BG'?'selected':''}>Bergamo (BG)</option><option value="BS" ${d.province==='BS'?'selected':''}>Brescia (BS)</option></select></label><label>${h(t('venue'))}<input name="venue" required maxlength="140" value="${h(d.venue||'')}"></label><label>${h(t('description'))}<textarea name="description" maxlength="1500">${h(d.description||'')}</textarea></label><label>${h(t('groupHistory'))}<textarea name="history" maxlength="1500">${h(d.history||'')}</textarea></label><label>${h(t('usualDay'))}<select name="weekday">${Array.from({length:7},(_,i)=>`<option value="${i}" ${Number(d.weekday??4)===i?'selected':''}>${h(t('day'+i))}</option>`).join('')}</select></label><div class="form-pair"><label>${h(t('startTime'))}<input name="start" type="time" value="${h(d.start||'20:30')}" required></label><label>${h(t('endTime'))}<input name="end" type="time" value="${h(d.end||'22:30')}" required></label></div>${accessFields({memberApproval:d.memberApproval===true||d.memberApproval==='true',bookingApproval:d.bookingApproval===true||d.bookingApproval==='true'})}<button type="submit" class="cta">${h(t('newGroup'))}</button>${button('cancel','nav','data-view="groups"')}</form>`;}
 function matchForm(){const old=ui.editMatchId?s.matches[ui.editMatchId]:null,g=s.groups[old?.groupId||ui.groupId];if(!g||!canManage(s,actor,g.id))return empty('unauthorized');const d=ui.drafts?.match||{};const value=(key,fallback)=>h(d[key]??fallback);return `${title(old?'editMatch':'newMatch')}<form class="card panel form-grid" id="matchForm" data-form="match"><p class="muted">${h(t('editNotice'))}</p><label>${h(t('groupFilter'))}<input value="${h(g.name)}" readonly></label><label>${h(t('date'))}<input type="date" name="date" required min="${dateKey(now)}" value="${value('date',old?.date||dateKey(now))}"></label><div class="form-pair"><label>${h(t('startTime'))}<input type="time" name="start" required value="${value('start',old?clock(old.startsAt):g.start)}"></label><label>${h(t('endTime'))}<input type="time" name="end" required value="${value('end',old?clock(old.endsAt):g.end)}"></label></div><label>${h(t('venue'))}<input name="venue" required maxlength="140" value="${value('venue',old?.venue||g.venue)}"></label><div class="form-pair"><label>${h(t('fee'))}<input name="price" required type="number" min="0" max="1000" step="0.01" value="${value('price',(old?.priceCents??g.priceCents)/100)}"></label><label>${h(t('capacity'))}<input name="capacity" required type="number" min="2" max="30" value="${value('capacity',old?.capacity||g.capacity||16)}"></label></div>${!old?`<label class="check-label"><input name="weekly" type="checkbox" ${d.weekly?'checked':''}>${h(t('weekly'))}</label><label>${h(t('until'))}<input name="until" type="date" value="${value('until',addDays(dateKey(now),56))}"></label><label class="check-label"><input name="skipHolidays" type="checkbox" ${d.skipHolidays===false?'':'checked'}>${h(t('skipHolidays'))}</label><p class="muted">${h(t('holidayHint'))}</p><div id="recurrencePreview" role="status">${recurrenceHTML(d)}</div>`:''}<button type="submit" class="cta">${h(t('save'))}</button>${button('cancel','open-group',`data-id="${g.id}"`)}</form>`;}
 function recurrenceHTML(d){const dates=occurrenceDates(d.date||dateKey(now),!!d.weekly,d.weekly?d.until||addDays(dateKey(now),56):d.date||dateKey(now),d.skipHolidays!==false);return `<p>${h(t('recurrencePreview',{n:dates.filter(x=>!x.skip).length,skipped:dates.filter(x=>x.skip).length}))}</p>${dates.slice(0,16).map(x=>`<small class="recurrence-date ${x.skip?'excluded':''}">${h(x.date)}${x.holiday?' · '+h(t(x.holiday)):''}</small>`).join('')}`;}
 function matchView(){const m=s.matches[ui.matchId];if(!m)return empty('notFound');const g=s.groups[m.groupId],list=activeBookings(s,m.id,now),confirmed=list.filter(b=>b.status==='confirmed'),mine=myBooking(s,actor,m.id,now),chosen=ui.selections?.[m.id],tab=ui.matchTab||'court',future=m.status==='active'&&Date.parse(m.startsAt)>now,manager=canManage(s,actor,g.id);const label=slot=>slot.startsWith('r')?t('reserve',{n:slot.slice(1)}):t('position',{n:ZONES[slot]});const seat=slot=>{const booking=list.find(b=>b.slot===slot),p=booking&&s.profiles[booking.personId],owned=p?.id===actor,pending=booking?.status==='pending',[x,y]=COORDS[slot]||[];return `<button type="button" class="${slot.startsWith('r')?'reserve-seat':'court-player '+(slot.startsWith('q')?'team-a':'team-b')} ${booking?pending?'held-seat':'taken-seat':'open-seat'} ${owned?'your-position':''} ${chosen===slot?'chosen':''}" ${x?`style="left:${x}%;top:${y}%"`:''} data-action="${p?'seat-profile':'select-seat'}" data-slot="${slot}" ${p?`data-person="${p.id}"`:''} aria-label="${h(label(slot)+' · '+(p?p.name:t('freeSeat'))+(pending?' · '+t('held'):''))}"><span class="seat-number">${h(slot.startsWith('r')?'R'+slot.slice(1):ZONES[slot])}</span>${p?avatar(p):'<span class="person-face free-plus" aria-hidden="true">+</span>'}<span class="seat-name">${h(p?p.name:t(slot.startsWith('r')?'selectReserve':'freeSeat',{n:slot.slice(1)}))}</span>${pending?`<span class="hold-tag">${h(t('status_pending'))}</span>`:''}</button>`;};return `${button('groupCard','open-group',`data-id="${g.id}"`,'back-link')}${title('matchDetails')}<article class="card match-summary"><h2>${h(g.name)}</h2>${organizer(g)}<p class="event-date">◷ ${h(date(m.startsAt))} · ${clock(m.startsAt)}–${clock(m.endsAt)}</p>${mapLink(g,m)}${m.organizerIssue?`<p class="validation-warning">${h(t(m.organizerIssue))}</p>`:''}<p class="capacity-summary">${h(t('registrationCount',{n:confirmed.length,pending:list.length-confirmed.length,total:m.capacity}))}</p><progress max="${m.capacity}" value="${list.length}" aria-label="${h(t('participants'))}"></progress></article><div class="match-tabs" role="tablist" aria-label="${h(t('matchDetails'))}">${['court','participants','info'].map(key=>`<button id="tab-${key}" type="button" role="tab" aria-selected="${tab===key}" aria-controls="match-${key}" data-action="match-tab" data-value="${key}">${h(t(key))}${key==='participants'?' ('+list.length+')':''}</button>`).join('')}</div><section id="match-court" role="tabpanel" aria-labelledby="tab-court" ${tab!=='court'?'hidden':''}><div class="court"><div class="court-floor">${FIELD.map(seat).join('')}<span class="court-net" aria-hidden="true"></span></div><p class="court-label">${h(t('available',{n:availableCount(s,m.id,now)}))}</p></div><div class="court-legend"><span class="legend-mine">${h(t('yourSpot'))}</span><span class="legend-a">${h(t('teamA'))}</span><span class="legend-b">${h(t('teamB'))}</span><span class="legend-held">${h(t('held'))}</span></div>${m.capacity>12?`<h2>${h(t('reserves'))}</h2><div class="reserve-list">${slotsFor(m).filter(x=>x.startsWith('r')).map(seat).join('')}</div>`:''}<p class="muted">${h(t('holdExplanation'))}</p>${chosen?`<p class="selected-label" role="status">${h(t('selectedSeat',{slot:label(chosen)}))}</p>`:''}</section><section id="match-participants" role="tabpanel" aria-labelledby="tab-participants" ${tab!=='participants'?'hidden':''}><div class="card panel participant-list">${!list.some(b=>b.personId===g.ownerId)?personRow(s.profiles[g.ownerId],t('organizerNotPlaying'),`<span class="organizer-badge">${h(t('organizer'))}</span>`):''}${list.map(b=>personRow(s.profiles[b.personId],label(b.slot),`${b.personId===g.ownerId?`<span class="organizer-badge">${h(t('organizer'))}</span>`:''}${badge(b.status)}${b.status==='pending'?`<small>${h(t('expires',{date:date(s.requests[b.requestId].expiresAt,true)}))}</small>`:''}`)).join('')||empty('noParticipants')}</div></section><section id="match-info" role="tabpanel" aria-labelledby="tab-info" ${tab!=='info'?'hidden':''}><article class="card panel info-block"><h2>${h(t('info'))}</h2><dl class="info-grid"><dt>${h(t('meeting'))}</dt><dd>${clock(m.meetingAt)}</dd><dt>${h(t('fee'))}</dt><dd>${money(m.priceCents)}</dd><dt>${h(t('warmup'))}</dt><dd>${clock(m.warmupStartsAt)}–${clock(m.startsAt)}<small>${h(t('warmupRule'))}</small></dd><dt>${h(t('playStarts'))}</dt><dd>${clock(m.startsAt)}</dd><dt>${h(t('eveningEnds'))}</dt><dd>${clock(m.endsAt)}</dd></dl></article><article class="card panel"><h2>${h(t('accessRules'))}</h2><p>${h(t(g.bookingApproval?'bookingManual':'bookingAuto'))}</p><p>${h(t('membersVsPlayers'))}</p><p>${h(t('refundRule'))}</p>${manager?button('editMatch','edit-match',`data-id="${m.id}"`):''}</article></section><section class="booking-actions">${!memberOf(s,actor,g.id)&&!mine?membershipGate(g):mine?`<div class="card panel"><h2>${h(t('yourBooking'))}</h2>${badge(mine.status)}<p>${h(label(mine.slot))}</p>${mine.status==='pending'?`<p>${h(t('expires',{date:date(s.requests[mine.requestId].expiresAt,true)}))}</p><p>${h(t('paymentWait'))}</p>`:mine.paymentStatus==='unpaid'?button('pay','payment',`data-id="${mine.id}"`):badge(mine.paymentStatus)}${chosen&&chosen!==mine.slot&&mine.status==='confirmed'?button('changeSeat','move-seat',`data-id="${mine.id}"`,'cta'):''}${future?button('cancelBooking','cancel-booking',`data-id="${mine.id}"`):''}</div>`:future?`<button type="button" id="bookButton" class="cta ${chosen?'booking-ready':''}" data-action="book" data-id="${m.id}" ${!availableCount(s,m.id,now)?'disabled':''}>${h(t(!availableCount(s,m.id,now)?'full':g.bookingApproval?'requestBooking':'book'))}</button>`:empty('matchClosed')}${manager?`<div class="manager-actions">${button('editMatch','edit-match',`data-id="${m.id}"`)}${button('duplicateMatch','duplicate-match',`data-id="${m.id}"`)}${button('requests','nav','data-view="requests"')}</div>`:''}${future&&(manager||mine?.status==='confirmed')?button('invitePlayer','invite-form',`data-id="${m.id}"`):''}</section>`;}
 function bookingsView(){const list=vals(s.bookings).filter(b=>b.personId===actor).sort((a,b)=>Date.parse(s.matches[b.matchId].startsAt)-Date.parse(s.matches[a.matchId].startsAt));return `${title('bookings')}${list.map(b=>{const m=s.matches[b.matchId],future=Date.parse(m.startsAt)>now;return `<article class="card panel booking-item"><h2>${h(groupName(m.groupId))}</h2><p>${h(date(m.startsAt,true))} · ${h(m.venue)}</p>${badge(b.status)}<p>${h(b.slot.startsWith('r')?t('reserve',{n:b.slot.slice(1)}):t('position',{n:ZONES[b.slot]}))}</p>${b.status==='pending'?`<p>${h(t('expires',{date:date(s.requests[b.requestId].expiresAt,true)}))}</p><p class="muted">${h(t('paymentWait'))}</p>`:''}<div class="button-row">${button('openMatch','open-match',`data-id="${m.id}"`)}${future&&['pending','confirmed'].includes(b.status)?button('cancelBooking','cancel-booking',`data-id="${b.id}"`):''}${future&&b.status==='confirmed'&&b.paymentStatus==='unpaid'?button('pay','payment',`data-id="${b.id}"`):''}${!future&&b.status==='confirmed'?s.ratings[`${m.id}:${actor}`]?badge('confirmed')+`<span>${h(t('ratingsSent'))}</span>`:button('rate','rate',`data-id="${m.id}"`):''}</div>${b.status==='confirmed'||b.paymentStatus!=='unpaid'?`<p>${h(t('fee'))}: ${money(b.priceCents)} · ${h(t('status_'+b.paymentStatus))}</p>`:''}</article>`;}).join('')||empty('noBookings')}`;}
 function requestsView(){const permitted=vals(s.groups).filter(g=>canManage(s,actor,g.id));if(!permitted.length)return title('requests')+empty('unauthorized');const list=vals(s.requests).filter(r=>canManage(s,actor,r.groupId)&&(!ui.requestGroup||r.groupId===ui.requestGroup)&&(!ui.requestType||r.type===ui.requestType)&&(!ui.requestStatus||r.status===ui.requestStatus)).sort((a,b)=>Date.parse(b.createdAt)-Date.parse(a.createdAt));const pending=list.filter(r=>r.status==='pending'),done=list.filter(r=>r.status!=='pending');const requestCard=r=>{const p=s.profiles[r.personId],m=s.matches[r.matchId];return `<article class="card panel request-item" data-request-id="${r.id}">${personRow(p,t(r.type))}<h3>${h(groupName(r.groupId))}</h3>${m?`<p>${h(date(m.startsAt,true))} · ${h(r.slot.startsWith('r')?t('reserve',{n:r.slot.slice(1)}):t('position',{n:ZONES[r.slot]}))}</p>`:''}<p>${h(t('requestCreated',{date:date(r.createdAt,true)}))}</p>${badge(r.status)}${r.expiresAt?`<p>${h(t('expires',{date:date(r.expiresAt,true)}))}</p>`:''}${r.status==='pending'?`<div class="button-row">${button('accept','decide',`data-id="${r.id}" data-accept="true"`,'small-primary')}${button('reject','decide',`data-id="${r.id}" data-accept="false"`)}</div>`:`<p class="muted">${h(t('by',{name:s.profiles[r.decidedBy]?.name||t('system')}))} · ${h(date(r.decidedAt,true))}</p>`}</article>`;};return `${title('requests')}<p class="muted">${h(t('requestsIntro'))}</p><div class="filter-panel"><label>${h(t('groupFilter'))}<select data-filter="requestGroup" id="requestGroup"><option value="">${h(t('all'))}</option>${permitted.map(g=>`<option value="${g.id}" ${ui.requestGroup===g.id?'selected':''}>${h(g.name)}</option>`).join('')}</select></label><label>${h(t('typeFilter'))}<select data-filter="requestType" id="requestType"><option value="">${h(t('all'))}</option>${['membership','booking'].map(k=>`<option value="${k}" ${ui.requestType===k?'selected':''}>${h(t(k))}</option>`).join('')}</select></label><label>${h(t('statusFilter'))}<select data-filter="requestStatus" id="requestStatus"><option value="">${h(t('all'))}</option>${['pending','accepted','rejected','expired','cancelled'].map(k=>`<option value="${k}" ${ui.requestStatus===k?'selected':''}>${h(t('status_'+k))}</option>`).join('')}</select></label></div><div class="request-list">${pending.map(requestCard).join('')||empty('noRequests')}</div><h2>${h(t('history'))}</h2><div class="request-history">${done.map(requestCard).join('')||empty('noHistory')}</div><details class="card panel"><summary>${h(t('history'))} · ${s.history.filter(x=>x.groupId&&canManage(s,actor,x.groupId)).length}</summary>${s.history.filter(x=>x.groupId&&canManage(s,actor,x.groupId)).slice().reverse().map(x=>`<p>${h(t('status_'+x.type))} · ${h(groupName(x.groupId))} · ${h(s.profiles[x.actorId]?.name||t('system'))} · ${h(date(x.createdAt,true))}</p>`).join('')}</details>`;}
 function notices(){const list=vals(s.notifications).filter(n=>n.recipientId===actor).sort((a,b)=>Date.parse(b.createdAt)-Date.parse(a.createdAt));return `${title('notifications')}${button('markRead','read-notices')}<div>${list.map(n=>{const r=s.requests[n.requestId],inv=s.invitations[n.invitationId];return `<article class="card panel notification-item ${n.read?'':'unread'}"><strong>${h(t('notice_'+n.type))}</strong><p>${h(groupName(n.groupId||s.matches[n.matchId]?.groupId))}</p><small>${h(date(n.createdAt,true))} · ${h(t(n.read?'read':'unread'))}</small>${r?personRow(s.profiles[r.personId],t(r.type)):''}<div class="button-row">${r&&canManage(s,actor,r.groupId)?button('goToRequests','notice',`data-id="${n.id}" data-view="requests"`):n.matchId?button('goToMatch','notice',`data-id="${n.id}" data-match="${n.matchId}"`):''}${inv?.status==='pending'?`${button('acceptInvite','decide-invite',`data-id="${inv.id}" data-accept="true"`)}${button('rejectInvite','decide-invite',`data-id="${inv.id}" data-accept="false"`)}`:''}</div>${inv?`<p class="muted">${h(t('invitationHint'))}</p>`:''}</article>`;}).join('')||empty('noNotifications')}</div>`;}
 function profileView(){const p=s.profiles[ui.profileId||actor];if(!p)return empty('notFound');const own=p.id===actor;return `${title('profileTitle')}<article class="card profile-hero">${avatar(p,'large')}<h2>${h(p.name)}</h2><span class="demo-chip">${h(t('fictionalAdult'))}</span><p>${h(t('role_'+p.role))} · ${h(t('level_'+p.level))}</p><p>${h(p.city)}</p><p>${h(p.bio||t('demoBio'))}</p><p class="photo-note">${h(t(photoAvailable(p)?p.photo.startsWith('assets/')?'artificialPhoto':'localPhoto':'photoFallback'))}</p>${own?button('editProfile','edit-profile'):''}</article><section class="card panel"><h2>${h(t('strengths'))}</h2><div class="profile-tags">${p.strengths.map(k=>`<span>${h(t(k))}</span>`).join('')}</div><h2>${h(t('availability'))}</h2><p>${h(t(p.available?'availablePlayer':'unavailablePlayer'))}</p><p>${p.days.map(d=>h(t('day'+d))).join(', ')}</p>${own?`<button type="button" class="secondary-cta" data-action="toggle-availability" aria-pressed="${p.available}">${h(t(p.available?'unavailablePlayer':'availablePlayer'))}</button><label class="upload-label">${h(t('uploadPhoto'))}<input type="file" id="photoUpload" accept="image/png,image/jpeg,image/webp"></label>${button('removePhoto','remove-photo')}<p class="muted">${h(t('photoHint'))}</p>`:''}</section>`;}
 function profileForm(){const p=person,d=ui.drafts?.profile||{};return `${title('editProfile')}<form class="card panel form-grid" data-form="profile" id="profileForm"><label>${h(t('name'))}<input name="name" maxlength="70" required value="${h(d.name??p.name)}"></label><label>${h(t('city'))}<input name="city" maxlength="80" value="${h(d.city??p.city)}"></label><label>${h(t('role'))}<select name="role">${ROLES.map(r=>`<option value="${r}" ${(d.role??p.role)===r?'selected':''}>${h(t('role_'+r))}</option>`).join('')}</select></label><label>${h(t('courtPosition'))}<select name="courtPosition">${Array.from({length:6},(_,i)=>i+1).map(n=>`<option value="${n}" ${Number(d.courtPosition??p.courtPosition??1)===n?'selected':''}>${h(t('position',{n}))}</option>`).join('')}</select><small>${h(t('organizerPositionHint'))}</small></label><label>${h(t('level'))}<select name="level">${['beginner','intermediate','advanced'].map(l=>`<option value="${l}" ${(d.level??p.level)===l?'selected':''}>${h(t('level_'+l))}</option>`).join('')}</select></label><label>${h(t('bio'))}<textarea name="bio" maxlength="1500">${h(d.bio??p.bio)}</textarea></label><fieldset><legend>${h(t('strengths'))}</legend>${['attack','reception','serve','defence','block'].map(k=>`<label class="check-label"><input type="checkbox" name="strengths" value="${k}" ${(d.strengths||p.strengths).includes(k)?'checked':''}>${h(t(k))}</label>`).join('')}</fieldset><fieldset><legend>${h(t('days'))}</legend>${Array.from({length:7},(_,i)=>`<label class="check-label"><input type="checkbox" name="days" value="${i}" ${(d.days||p.days).map(Number).includes(i)?'checked':''}>${h(t('day'+i))}</label>`).join('')}</fieldset><button type="submit" class="cta">${h(t('saveProfile'))}</button>${button('cancel','nav','data-view="profile"')}</form>`;}
 function settingsView(){return `${title('settings')}<section class="card panel"><label for="themeSelect">${h(t('theme'))}</label><select id="themeSelect" data-setting="theme">${['light','dark','auto'].map(k=>`<option value="${k}" ${settings.theme===k?'selected':''}>${h(t(k))}</option>`).join('')}</select><label for="languageSelect">${h(t('language'))}</label><select id="languageSelect" data-setting="language"><option value="it" ${settings.language==='it'?'selected':''}>Italiano</option><option value="en" ${settings.language==='en'?'selected':''}>English</option></select></section><section class="card panel"><label for="previewSelect">${h(t('devicePreview'))}</label><select id="previewSelect" data-setting="preview">${['auto','mobile','tablet','desktop'].map(k=>`<option value="${k}" ${(settings.preview||'auto')===k?'selected':''}>${h(t(k))}</option>`).join('')}</select><h2>${h(t('prototype'))}</h2><p class="muted">${h(t('demoExplanation'))}</p><p>${h(t('holdConfigHint'))}</p>${s.authorizedAdmins.includes(actor)?`<form data-form="hold-config"><label>${h(t('holdHours'))}<input name="hours" type="number" min="0.01" max="168" step="0.01" value="${s.config.holdHours}" required></label><button class="secondary-cta" type="submit">${h(t('save'))}</button></form><form data-form="admin-gate"><label>${h(t('adminCode'))}<input type="password" name="code" inputmode="numeric" autocomplete="off"></label><button class="secondary-cta" type="submit">${h(t('openAdmin'))}</button></form>`:`<p class="muted">${h(t('adminHint'))}</p>`}${button('downloadData','export')}${button('resetDemo','reset')}</section>`;}
 function admin(){if(!s.authorizedAdmins.includes(actor)||!ui.adminUnlocked)return empty('unauthorized');const list=vals(s.payments),charges=list.filter(p=>p.type==='charge'),refunds=list.filter(p=>p.type==='refund');return `${title('admin')}<p class="muted">${h(t('demoExplanation'))}</p><div class="metrics"><article class="card panel"><h2>${h(t('charges'))}</h2><strong>${money(charges.reduce((a,p)=>a+p.totalCents,0))}</strong></article><article class="card panel"><h2>${h(t('commission'))}</h2><strong>${money(charges.reduce((a,p)=>a+p.feeCents,0))}</strong></article><article class="card panel"><h2>${h(t('refunds'))}</h2><strong>${money(refunds.reduce((a,p)=>a+p.amountCents,0))}</strong></article></div>${list.slice().reverse().map(p=>{const b=s.bookings[p.bookingId];return `<article class="card panel"><strong>${h(groupName(s.matches[b.matchId].groupId))}</strong><p>${h(s.profiles[b.personId].name)} · ${h(date(p.createdAt,true))}</p><p>${h(p.method)} · ${h(t(p.type==='refund'?'refunds':'payment'))}: ${money(p.totalCents)}</p><small>${h(t('commission'))}: ${money(p.feeCents)}</small></article>`;}).join('')||empty('noPayments')}`;}
 function invitationForm(){const m=s.matches[ui.matchId];if(!m)return empty('notFound');const q=(ui.inviteSearch||'').toLocaleLowerCase(),people=vals(s.profiles).filter(p=>p.id!==actor&&p.available&&!myBooking(s,p.id,m.id,now)&&`${p.name} ${t('role_'+p.role)}`.toLocaleLowerCase().includes(q));return `${title('invitePlayer')}<label class="sr-only" for="inviteSearch">${h(t('search'))}</label><input id="inviteSearch" type="search" data-filter="inviteSearch" value="${h(ui.inviteSearch||'')}" placeholder="${h(t('search'))}"><div class="card panel">${people.map(p=>{const sent=vals(s.invitations).some(i=>i.matchId===m.id&&i.recipientId===p.id&&i.status==='pending');return personRow(p,'',`<button type="button" class="small-primary" data-action="invite" data-id="${p.id}" ${sent?'disabled':''}>${h(t(sent?'inviteSent':'invite'))}</button>`);}).join('')}</div>`;}
 function ratingView(){const m=s.matches[ui.matchId];if(!m)return empty('notFound');const list=vals(s.bookings).filter(b=>b.matchId===m.id&&b.status==='confirmed'&&b.personId!==actor);return `${title('rate')}<p class="muted">${h(t('ratingHelp'))}</p><form data-form="rating" class="card panel">${ratingMetric('venue',t('venueRating'))}${list.map(b=>`<section class="rating-person"><h2>${h(s.profiles[b.personId].name)}</h2>${ratingMetric('reliability:'+b.personId,t('reliability'))}${ratingMetric('technique:'+b.personId,t('technique'))}</section>`).join('')}<button type="submit" class="cta">${h(t('submitRatings'))}</button></form>`;}
 function ratingMetric(name,label){return `<fieldset class="rating-stars"><legend>${h(label)}</legend>${[1,2,3,4,5].map(n=>`<label title="${n}/5"><input type="radio" name="${h(name)}" value="${n}"><span>★</span><span class="sr-only">${n}/5</span></label>`).join('')}</fieldset>`;}
 function paymentDialog(b){const m=s.matches[b.matchId],fee=Math.round(b.priceCents*.05);return `<h2 id="dialogTitle">${h(t('payment'))}</h2><p>${h(t('paymentIntro'))}</p><form data-form="payment" data-id="${b.id}"><label>${h(t('method'))}<select name="method"><option>Satispay</option><option>PayPal</option></select></label><dl class="info-grid"><dt>${h(t('fee'))}</dt><dd>${money(b.priceCents)}</dd><dt>${h(t('commission'))}</dt><dd>${money(fee)}</dd><dt>${h(t('total'))}</dt><dd><strong>${money(b.priceCents+fee)}</strong></dd></dl><button type="submit" id="confirmDemoPayment" class="cta">${h(t('pay'))}</button>${button('cancel','close-dialog')}</form>`;}
 function paymentReminder(){const due=vals(s.bookings).filter(b=>b.personId===actor&&b.status==='confirmed'&&b.paymentStatus==='unpaid'&&b.priceCents>0&&s.matches[b.matchId]?.status==='active'&&Date.parse(s.matches[b.matchId].startsAt)>now).sort((a,b)=>Date.parse(s.matches[a.matchId].startsAt)-Date.parse(s.matches[b.matchId].startsAt));if(!due.length)return '';const b=due[0],m=s.matches[b.matchId];return `<div class="payment-reminder-copy"><strong>${h(t('paymentDueTitle'))}</strong><span>${h(groupName(m.groupId))} · ${money(b.priceCents+Math.round(b.priceCents*.05))}</span><small>${h(t(due.length>1?'paymentsDueCount':'paymentDueHint',{n:due.length}))}</small></div><button type="button" class="small-primary" data-action="payment" data-id="${b.id}">${h(t('payNow'))}</button>${due.length>1?button('viewDueBookings','nav','data-view="bookings"','payment-reminder-all'):''}`;}
 const renderers={explore,groups:directory,group:groupCard,groupForm,match:matchView,matchForm,bookings:bookingsView,requests:requestsView,notifications:notices,profile:profileView,profileForm,settings:settingsView,admin,invite:invitationForm,rating:ratingView};
 return {html:(renderers[ui.view]||explore)(),paymentReminder,avatar,button,money,date,paymentDialog,recurrenceHTML,upcoming,groupMembers};
}
